import { OfferLib, Offer, OfferType } from './mangrove/libraries/OfferLib.sol';
import { VaultErrors } from './errors/VaultErrors.sol';

/**
 * @dev RangeProtocolMangroveVault is an ERC20 compatible vault shares token contract that accepts a pair of tokens from
 * the user and deposit it into its Kandle running on Mangrove. A has a base(token0) and quote(token1) token. The tokens
 * are provided by the user based on the vault's underlying balance ratio of token0 and token1. If the underlying balances
 * of the vault are zero then the midTick defined by manager is used to calculate the ratio of token0 and token1 user
 * has to deposit to mint vault shares.
 * The user can mint vault shares by deposit token0 and token1 in a specific ratio and burn their vault shares to redeem
 * their shares of token0 and token1. A user's owed ratio of token0 and token1 is pro-rata based on the amount of vault
 * shares they own against the total supply of the vault.
 * The manager of the vault can create initial position on the vault, remove liquidity from Kandel and add liquidity
 * to Kandel.
 * The manager can also collect their fee earned in token0 and token1.
 */
contract RangeProtocolMangroveVault is
    Initializable,
    UUPSUpgradeable,
    ReentrancyGuardUpgradeable,
    OwnableUpgradeable,
    ERC20Upgradeable,
    PausableUpgradeable,
    RangeProtocolMangroveVaultStorage
{
    uint256 public constant MAX_MANAGING_FEE = 1000;

    constructor() {
        _disableInitializers();
    }

    /**
     * @notice initalizes the vault's initial state.
     * @param kandel_ the address of vault's Kandel contract.
     * @param data additional data associated with the vault that is needed for initialization.
     */
    function initialize(address kandel_, bytes memory data) external override initializer {
        (address MGV_, address manager_, string memory name_, string memory symbol_) =
            abi.decode(data, (address, address, string, string));

        __UUPSUpgradeable_init();
        __ReentrancyGuard_init();
        __Ownable_init();
        __ERC20_init(name_, symbol_);
        __Pausable_init();

        _transferOwnership(manager_);
        _factory = msg.sender;
        _kandel = IBlastKandel(kandel_);
        _MGV = IMGV(MGV_);
        _token0 = _kandel.BASE();
        _token1 = _kandel.QUOTE();

        // set managing fee to 1% be default.
        _setManagingFee(100);
    }

    /**
     * @notice allows pausing of minting and burning features of the contract in the event
     * any security risk is seen in the vault.
     */
    function pause() external override onlyManager {
        _pause();
    }

    /**
     * @notice allows unpausing of minting and burning features of the contract if they paused.
     */
    function unpause() external override onlyManager {
        _unpause();
    }

    /**
     * @notice sets the managing fee.
     * @param managingFee_ new managing fee.
     */
    function setManagingFee(uint256 managingFee_) external override onlyManager {
        _setManagingFee(managingFee_);
    }

    /**
     * @notice allows manager to set initial parameters for the vault to accept token0 and token1 in specific ratio.
     * @param position_ the position data to set.
     */
    function createPosition(Position calldata position_) external payable override onlyManager {
        if (_inPosition) revert VaultErrors.PositionAlreadyCreated();
        _MGV.fund{ value: msg.value }(address(_kandel));
        _position = position_;
        _inPosition = true;

        emit PositionCreated(position_);
    }

    /**
     * @notice funds the mangrove contract with offers bounty.
     */
    function fundMangrove() external payable override {
        _MGV.fund{ value: msg.value }(address(_kandel));
    }

    /**
     * @notice removes bounty funds from mangrove contract.
     * @param amount the amount of bounty amount to withdraw. passing max uint will return the amount of free provisions.
     * @param receiver the address to receive the withdrawn bounty.
     */
    function withdrawFromMangrove(uint256 amount, address payable receiver) external override onlyManager {
        _kandel.withdrawFromMangrove(amount, receiver);
    }

    struct MintVars {
        IERC20 token0;
        IERC20 token1;
        uint256 totalSupply;
        IBlastKandel kandel;
        bool inPosition;
        Position position;
    }

    /**
     * @notice allows user to mint vault shares. The token0 and token1 are added to the Kandle if there is an active
     * position set by the manager. The user is minted the vault shares based on the vault's ratio of token0 and token1.
     * @param mintAmount the amount of vault shares user wants to mint.
     * @param maxAmountsIn the maximum amounts of token0 and token1 user wants to deposit.
     * @return amount0 the amount of token0 transferred from user.
     * @return amount1 the amount of token1 transferred from user.
     */
    function mint(
        uint256 mintAmount,
        uint256[2] calldata maxAmountsIn
    )
        external
        override
        nonReentrant
        whenNotPaused
        returns (uint256 amount0, uint256 amount1)
    {
        if (mintAmount == 0) revert VaultErrors.ZeroMintAmount();
        MintVars memory vars = MintVars(_token0, _token1, totalSupply(), _kandel, _inPosition, _position);
        if (vars.totalSupply != 0) {
            (uint256 amount0Current, uint256 amount1Current) = getUnderlyingBalances();
            amount0 = FullMath.mulDivRoundingUp(mintAmount, amount0Current, vars.totalSupply);
            amount1 = FullMath.mulDivRoundingUp(mintAmount, amount1Current, vars.totalSupply);
        } else if (vars.inPosition) {
            amount0 = mintAmount;
            amount1 = TickLib.inboundFromOutbound(_position.midTick, amount0);
        } else {
            revert VaultErrors.MintNotAllowed();
        }

        if (amount0 > maxAmountsIn[0] || amount1 > maxAmountsIn[1]) revert VaultErrors.SlippageExceedThreshold();

        UserVault storage userVault = _userVaults[msg.sender];
        if (userVault.user == address(0x0)) {
            userVault.user = msg.sender;
            _users.push(msg.sender);
        }
        userVault.token0 += amount0;
        userVault.token1 += amount1;

        if (amount0 != 0) {
            vars.token0.transferFrom(msg.sender, address(this), amount0);
        }
        if (amount1 != 0) {
            vars.token1.transferFrom(msg.sender, address(this), amount1);
        }

        _mint(msg.sender, mintAmount);
        if (vars.inPosition) {
            // there is an active position, deposit funds to the Kandel.
            vars.token0.approve((address(vars.kandel)), amount0);
            vars.token1.approve(address(vars.kandel), amount1);
            vars.kandel.depositFunds(amount0, amount1);

            // calculate the first tick of the position based on the mid tick.
            Tick baseQuoteTickIndex0 = Tick.wrap(
                (Tick.unwrap(vars.position.midTick))
                    - int256(vars.position.baseQuoteTickOffset * vars.position.firstAskIndex)
                    + int256(vars.position.baseQuoteTickOffset) / 2
            );

            // calculate the current ask index.
            uint256 _firstAskIndex = _currentFirstAskIndex();
            _kandel.populateChunkFromOffset(
                0,
                vars.position.pricePoints,
                baseQuoteTickIndex0,
                _firstAskIndex,
                vars.token1.balanceOf(address(vars.kandel)), // bidGives
                vars.token0.balanceOf(address(vars.kandel)) // askGives
            );
        }

        emit Minted(msg.sender, mintAmount, amount0, amount1);
    }

    struct BurnVars {
        IERC20 token0;
        IERC20 token1;
        bool inPosition;
        IBlastKandel kandel;
        uint256 totalSupply;
        uint256 userSharesBefore;
        Position position;
    }

    /**
     * @notice allows user to burn their vault shares. A user is transferred the pro-rata amounts of token0 and token1
     * upon burning their shares of the vault.
     * @param burnAmount the amount of vault shares to burn from user.
     * @param minAmountsOut the minimum amounts of token0 and token1 to get by burning {burnAmount}
     * @return amount0 the amount of token0 user gets by burning the vault shares.
     * @return amount1 the amount of token1 user gets by burning the vault shares.
     */
    function burn(
        uint256 burnAmount,
        uint256[2] calldata minAmountsOut
    )
        external
        override
        nonReentrant
        returns (uint256 amount0, uint256 amount1)
    {
        if (burnAmount == 0) revert VaultErrors.ZeroBurnAmount();
        BurnVars memory vars =
            BurnVars(_token0, _token1, _inPosition, _kandel, totalSupply(), balanceOf(msg.sender), _position);
        _burn(msg.sender, burnAmount);

        (uint256 amount0Current, uint256 amount1Current) = getUnderlyingBalances();

        amount0Current -= _managerBalance0;
        amount1Current -= _managerBalance1;

        amount0 = amount0Current * burnAmount / vars.totalSupply;
        amount1 = amount1Current * burnAmount / vars.totalSupply;

        if (vars.inPosition) {
            // there is an active position, withdraw funds from the kandel.
            vars.kandel.withdrawFunds(amount0, amount1, address(this));

            // calculate the first tick of the position based on the mid tick.
            Tick baseQuoteTickIndex0 = Tick.wrap(
                (Tick.unwrap(vars.position.midTick))
                    - int256(vars.position.baseQuoteTickOffset * vars.position.firstAskIndex)
                    + int256(vars.position.baseQuoteTickOffset) / 2
            );

            // calculate index of the first current ask.
            uint256 _firstAskIndex = _currentFirstAskIndex();
            _kandel.populateChunkFromOffset(
                0,
                vars.position.pricePoints,
                baseQuoteTickIndex0,
                _firstAskIndex,
                vars.token1.balanceOf(address(vars.kandel)), // bidGives
                vars.token0.balanceOf(address(vars.kandel)) // askGives
            );
        }

        UserVault storage userVault = _userVaults[msg.sender];
        userVault.token0 = (userVault.token0 * (vars.userSharesBefore - burnAmount)) / vars.userSharesBefore;
        userVault.token1 = (userVault.token1 * (vars.userSharesBefore - burnAmount)) / vars.userSharesBefore;

        _applyManagingFee(amount0, amount1);
        (amount0, amount1) = _netManagingFee(amount0, amount1);

        if (amount0 < minAmountsOut[0] || amount1 < minAmountsOut[1]) revert VaultErrors.SlippageExceedThreshold();

        vars.token0.transfer(msg.sender, amount0);
        vars.token1.transfer(msg.sender, amount1);

        emit Burned(msg.sender, burnAmount, amount0, amount1);
    }

    /**
     * @notice removes liquidity from kandel and transfer to the vault. This function removes the active position on
     * Kandel.
     */
    function removeLiquidity() external override onlyManager {
        if (!_inPosition) revert VaultErrors.NotInPosition();
        IBlastKandel kandel_ = _kandel;
        kandel_.retractOffers(0, _position.pricePoints);
        uint256 token0Amount = _token0.balanceOf(address(kandel_));
        uint256 token1Amount = _token1.balanceOf(address(kandel_));
        kandel_.withdrawFunds(token0Amount, token1Amount, address(this));

        delete _position;
        _inPosition = false;

        emit LiquidityRemoved(Tick.unwrap(_position.midTick), token0Amount, token1Amount);
    }

    /**
     * @notice adds liquidity to the Kandel by moving token0 and token1 from vault to the Kandel.
     * @param position_ the position to create on the Kandel.
     * @param token0Amount the amount of token0 to add to the position.
     * @param token1Amount the amount of token1 to add to the position.
     */
    function addLiquidity(
        Position calldata position_,
        uint256 token0Amount,
        uint256 token1Amount
    )
        external
        override
        onlyManager
    {
        if (_inPosition) revert VaultErrors.AlreadyInPosition();
        IBlastKandel kandle_ = _kandel;
        _token0.approve(address(kandle_), token0Amount);
        _token1.approve(address(kandle_), token1Amount);

        IBlastKandel.Params memory params =
            IBlastKandel.Params(position_.gasprice, position_.gasreq, position_.stepSize, position_.pricePoints);

        // compute the first tick of the position based on the mid tick.
        Tick baseQuoteTickIndex0 = Tick.wrap(
            (Tick.unwrap(position_.midTick)) - int256(position_.baseQuoteTickOffset * position_.firstAskIndex)
                + int256(position_.baseQuoteTickOffset) / 2
        );

        // populate the kandel with the position data.
        kandle_.populateFromOffset(
            0, // from
            position_.pricePoints, // to
            baseQuoteTickIndex0,
            position_.baseQuoteTickOffset,
            position_.firstAskIndex,
            token1Amount, // bid gives
            token0Amount,
            params,
            token0Amount,
            token1Amount
        );
        _position = position_;
        _inPosition = true;

        emit LiquidityAdded(Tick.unwrap(position_.midTick), token0Amount, token1Amount);
    }

    // @notice allows manager to collect the fee in token0 and token1.
    function collectManagerBalance() external override onlyManager {
        uint256 managerBalance0_ = _managerBalance0;
        uint256 managerBalance1_ = _managerBalance1;
        _managerBalance0 = 0;
        _managerBalance1 = 0;
        _token0.transfer(msg.sender, managerBalance0_);
        _token1.transfer(msg.sender, managerBalance1_);
    }

    /**
     * @notice returns the amounts of token0, token1 and mint amount based on the passed amounts of token0 and token1
     * intended to be deposited.
     * If the total supply of the vault is non-zero then the mint amount returned is based on the ratio of the token amounts
     * passed to the function and the vault holding of the tokens.
     * If the total supply is zero then amount0 becomes the mint amount and amount1 is computed based on amount0 using TickLib library.
     * @param amount0Max the maximum amount of token0 to deposit.
     * @param amount1Max the maximum amount of token1 to deposit.
     * @return amount0 the actual amount of token0 to deposit.
     * @return amount1 the actual amount of token1 to deposit.
     * @return mintAmount the vault shares to be minted against the deposit of amount0 and amount1.
     */
    function getMintAmounts(
        uint256 amount0Max,
        uint256 amount1Max
    )
        external
        view
        override
        returns (uint256 amount0, uint256 amount1, uint256 mintAmount)
    {
        uint256 _totalSupply = totalSupply();
        if (_totalSupply != 0) {
            (uint256 amount0Current, uint256 amount1Current) = getUnderlyingBalances();
            if (amount0Current == 0 && amount1Current != 0) {
                mintAmount = FullMath.mulDiv(amount1Max, _totalSupply, amount1Current);
            } else if (amount0Current != 0 && amount1Current == 0) {
                mintAmount = FullMath.mulDiv(amount0Max, _totalSupply, amount0Current);
            } else if (amount0Current == 0 && amount1Current == 0) {
                revert VaultErrors.ZeroUnderlyingBalance();
            } else {
                uint256 amount0Mint = FullMath.mulDiv(amount0Max, _totalSupply, amount0Current);
                uint256 amount1Mint = FullMath.mulDiv(amount1Max, _totalSupply, amount1Current);
                if (amount0Mint == 0 || amount1Mint == 0) revert VaultErrors.ZeroMintAmount();
                mintAmount = amount0Mint < amount1Mint ? amount0Mint : amount1Mint;
            }

            amount0 = FullMath.mulDivRoundingUp(mintAmount, amount0Current, _totalSupply);
            amount1 = FullMath.mulDivRoundingUp(mintAmount, amount1Current, _totalSupply);
        } else if (_inPosition) {
            amount1 = TickLib.inboundFromOutbound(_position.midTick, amount0Max);
            if (amount1 > amount1Max) {
                amount1 = amount1Max;
                amount0 = TickLib.outboundFromInbound(_position.midTick, amount1);
            } else {
                amount0 = amount0Max;
            }
            mintAmount = amount0;
        }
    }

    /**
     * @notice returns the underlying balances of the vault in token0 and token1.
     * If the there is an active position then the underlying balance is the balance of Kandle in token0 and token1,
     * otherwise it is the passive balance of token0 and token1 in the vault.
     * @return amount0Current the amount of vault's underlying balance in token0.
     * @return amount1Current the amount of vault's underlying balance in token1.
     */
    function getUnderlyingBalances() public view override returns (uint256 amount0Current, uint256 amount1Current) {
        (amount0Current, amount1Current) = _inPosition
            ? (_token0.balanceOf(address(_kandel)), _token1.balanceOf(address(_kandel)))
            : (_token0.balanceOf(address(this)), _token1.balanceOf(address(this)));

        amount0Current -= _managerBalance0;
        amount1Current -= _managerBalance1;
    }

    /**
     * @notice returns the underlying balance based on the amount of shares passed to the function.
     * @param shares the amount of shares to calculate the underlying balances against.
     * @return amount0 the amount of token0 in underlying balance against the shares.
     * @return amount1 the amount of token1 in underlying balance against the shares.
     */
    function getUnderlyingBalancesByShare(uint256 shares)
        public
        view
        override
        returns (uint256 amount0, uint256 amount1)
    {
        uint256 totalSupply_ = totalSupply();
        if (totalSupply_ != 0 && shares <= totalSupply_) {
            (uint256 amount0Current, uint256 amount1Current) = getUnderlyingBalances();
            amount0 = amount0Current * shares / totalSupply_;
            amount1 = amount1Current * shares / totalSupply_;

            (amount0, amount1) = _netManagingFee(amount0, amount1);
        }
    }

    /**
     * @notice _authorizeUpgrade internally called by UUPS contract to validate the upgrading operation of
     * the contract.
     */
    function _authorizeUpgrade(address) internal view override {
        if (msg.sender != _factory) revert VaultErrors.OnlyFactoryAllowed();
    }

    /**
     * @notice nets/subtracts the managing fee from the amounts passed to the function and returns the amounts after
     * netting managing fee from amounts of token0 and token1.
     * @param amount0 the amount of token0 to net the managing fee from.
     * @param amount1 the amount of token1 to net the managing fee from.
     */
    function _netManagingFee(uint256 amount0, uint256 amount1) private view returns (uint256, uint256) {
        uint256 managingFee_ = _managingFee;
        return (amount0 - (amount0 * managingFee_ / 10_000), amount1 - (amount1 * managingFee_ / 10_000));
    }

    /**
     * @notice applies managing on amount0 and amount1 and adds it to the manager's balance.
     * @param amount0 the amount of token0 to net the managing fee from.
     * @param amount1 the amount of token1 to net the managing fee from.
     */
    function _applyManagingFee(uint256 amount0, uint256 amount1) private {
        uint256 managingFee_ = _managingFee;
        _managerBalance0 += amount0 * managingFee_ / 10_000;
        _managerBalance1 += amount1 * managingFee_ / 10_000;
    }

    /**
     * @notice sets the managing fee.
     * @param managingFee_ the managing fee to set.
     */
    function _setManagingFee(uint256 managingFee_) private {
        if (managingFee_ > MAX_MANAGING_FEE) revert VaultErrors.MaxFeeExceeded();
        _managingFee = managingFee_;
        emit ManagingFeeSet(managingFee_);
    }

    /**
     * @notice updates the userVaults for sender and recipient.
     * @param from the sender of the vault shares.
     * @param to the recipient of the vault shares.
     * @param value the amount of vault shares to be transferred.
     */
    function _update(address from, address to, uint256 value) internal override {
        super._update(from, to, value);
        // for mint and burn the user vaults adjustment are handled in the respective functions
        if (from == address(0x0) || to == address(0x0)) return;
        if (_userVaults[to].user == address(0x0)) {
            _userVaults[to].user = to;
            _users.push(to);
        }

        uint256 senderBalanceBefore = balanceOf(from);
        uint256 senderBalanceAfter = senderBalanceBefore - value;
        uint256 token0Amount =
            _userVaults[from].token0 - (_userVaults[from].token0 * senderBalanceAfter) / senderBalanceBefore;

        uint256 token1Amount =
            _userVaults[from].token1 - (_userVaults[from].token1 * senderBalanceAfter) / senderBalanceBefore;

        _userVaults[from].token0 -= token0Amount;
        _userVaults[from].token1 -= token1Amount;

        _userVaults[to].token0 += token0Amount;
        _userVaults[to].token1 += token1Amount;
    }

    /**
     * @notice returns the index of the first ask offer in the position.
     * @return i the index of the first ask offer.
     */
    function _currentFirstAskIndex() private view returns (uint256 i) {
        uint256 _pricePoints = _position.pricePoints;
        for (; i < _pricePoints; i++) {
            Offer offer = _kandel.getOffer(OfferType.Bid, i);
            if (OfferLib.gives(offer) == 0) {
                break;
            }
        }
    }
}

