pragma solidity 0.8.20;

import { IERC20 } from 'openzeppelin-contracts/contracts/token/ERC20/IERC20.sol';
import { IBlastKandel } from '../mangrove/interfaces/IBlastKandel.sol';
import { IMGV } from '../mangrove/interfaces/IMGV.sol';
import { Tick } from '../mangrove/libraries/TickLib.sol';


    struct UserVault {
        address user;
        uint256 token0;
        uint256 token1;
    }

    event Minted(address indexed receiver, uint256 mintAmount, uint256 amount0In, uint256 amount1In);
    event Burned(address indexed receiver, uint256 burnAmount, uint256 amount0Out, uint256 amount1Out);
    event LiquidityAdded(int256 midTick, uint256 amount0In, uint256 amount1In);
    event LiquidityRemoved(int256 midTick, uint256 amount0Out, uint256 amount1Out);
    event PositionCreated(Position position);
    event ManagingFeeSet(uint256 managingFee);

    function initialize(address kandel_, bytes memory data) external;
    function pause() external;
    function unpause() external;
    function createPosition(Position calldata position_) external payable;
    function fundMangrove() external payable;
    function withdrawFromMangrove(uint256 amount, address payable receiver) external;
    function setManagingFee(uint256 managingFee) external;
    function mint(
